    def _generate_function_stub(
        self,
        name: str,
        func: Optional[Union[Callable, classmethod]] = None,
        sign: Optional[List[inspect.Signature]] = None,
        indentation: Optional[str] = None,
        doc: Optional[str] = None,
        deco: Optional[str] = None,
    ) -> str:
        """Emit signatures without executing the callable or its descriptors."""
        if func is None and (sign is None or doc is None):
            raise RuntimeError(
                "A function, or signatures and documentation, must be provided"
            )
        indentation = indentation or ""
        if isinstance(func, (classmethod, staticmethod)):
            if deco is None:
                deco = (
                    "@classmethod" if isinstance(func, classmethod) else "@staticmethod"
                )
            func = func.__func__
        elif inspect.ismethod(func) and isinstance(func.__self__, type):
            if deco is None:
                deco = "@classmethod"
            func = func.__func__
        if doc is None:
            doc = getattr(func, "__doc__", None) or ""
        if "STUBGEN_IGNORE" in doc:
            return ""
        if sign is None:
            sign = self._function_signatures(func)

        overloaded = len(sign) > 1
        if overloaded:
            self._imports.add("typing")
        result = StringIO()
        for signature in sign:
            parameters = []
            positional_only = False
            keyword_separator = False
            for parameter in signature.parameters.values():
                kind = parameter.kind
                if positional_only and kind is not inspect.Parameter.POSITIONAL_ONLY:
                    parameters.append("/")
                    positional_only = False
                if kind is inspect.Parameter.POSITIONAL_ONLY:
                    positional_only = True
                if kind is inspect.Parameter.KEYWORD_ONLY and not keyword_separator:
                    parameters.append("*")
                    keyword_separator = True
                prefix = ""
                if kind is inspect.Parameter.VAR_POSITIONAL:
                    prefix = "*"
                    keyword_separator = True
                elif kind is inspect.Parameter.VAR_KEYWORD:
                    prefix = "**"
                annotation = self._exploit_annotation(parameter.annotation)
                text = prefix + parameter.name + annotation
                if parameter.default is not inspect.Parameter.empty:
                    text += (" = " if annotation else "=") + self._format_default(
                        parameter.default
                    )
                parameters.append(text)
            if positional_only:
                parameters.append("/")

            return_type = signature.return_annotation
            if return_type is None or (
                name == "__init__" and return_type is inspect.Signature.empty
            ):
                return_type = type(None)
            if overloaded:
                result.write(indentation + "@typing.overload\n")
            if deco:
                for decorator in deco.splitlines():
                    result.write(indentation + decorator + "\n")
            is_async = inspect.iscoroutinefunction(func) or inspect.isasyncgenfunction(func)
            result.write(
                indentation
                + ("async def " if is_async else "def ")
                + name + "(" + ", ".join(parameters) + ")"
                + self._exploit_annotation(return_type, " -> ")
                + ":\n"
            )
            if doc:
                result.write(self._format_docstring(doc, indentation + TAB))
            result.write(indentation + TAB + "...\n\n")
        return result.getvalue()

    def _generate_generic_stub(self, element_name: str, element: Any) -> str:
        return "{0}: {1}\n".format(
            element_name, self._get_element_name_with_module(type(element))
        )

